// Regression: after Apply, the brush overlay (red/pink mask) must be cleared,
// and the result watermark area must have no pink residue. Runs on live or
// local URL (PAGE_URL env). Pink-stamp test image generated by gen-pink-png.mjs.
import puppeteer from 'puppeteer-core'
import { fileURLToPath } from 'node:url'

const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'
const PAGE_URL = process.env.PAGE_URL || 'https://www.superpixmia.com/remove-watermark'
const PNG = fileURLToPath(new URL('./test-pink-watermark.png', import.meta.url))
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

const browser = await puppeteer.launch({ executablePath: EDGE, headless: 'new', args: ['--no-sandbox'] })
const page = await browser.newPage()
await page.setViewport({ width: 1280, height: 900 })
await page.goto(PAGE_URL, { waitUntil: 'networkidle2', timeout: 60000 })
const input = await page.$('input[type="file"]')
await input.uploadFile(PNG)
await sleep(1500)

const stage = await page.evaluate(() => {
  const s = document.querySelector('canvas.cursor-crosshair')
  const r = s.getBoundingClientRect()
  return { left: r.left, top: r.top, width: r.width, height: r.height, bw: s.width, bh: s.height }
})
// Watermark block: buffer x[70,130], y[50,100] (see gen-pink-png.mjs).
const mapToScreen = (s, bx, by) => ({
  x: s.left + (bx / s.bw) * s.width,
  y: s.top + (by / s.bh) * s.height,
})

// Full-cover paint of the watermark.
for (const [x1, y1, x2, y2] of [[72, 55, 128, 55], [72, 75, 128, 75], [72, 95, 128, 95]]) {
  const a = mapToScreen(stage, x1, y1)
  const b = mapToScreen(stage, x2, y2)
  await page.mouse.move(a.x, a.y); await page.mouse.down()
  await page.mouse.move(b.x, b.y, { steps: 8 }); await page.mouse.up()
}
await sleep(400)

// Overlay = the mask canvas (red brush strokes, drawn at full alpha).
// It's the sibling of the stage canvas inside the editor's relative wrapper.
const overlayHasStrokes = () => page.evaluate(() => {
  const stage = document.querySelector('canvas.cursor-crosshair')
  if (!stage) return -1
  const host = stage.parentElement
  const c = host && host.querySelector('canvas:not(.cursor-crosshair)')
  if (!c) return -2
  const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data
  for (let i = 3; i < d.length; i += 4) if (d[i] > 128) return 1
  return 0
})

const before = await overlayHasStrokes()

const clicked = await page.evaluate(() => {
  const btns = Array.from(document.querySelectorAll('button'))
  const el = btns.find((x) => /Remove Watermark|开始去水印/.test(x.textContent || ''))
  if (el) { el.click(); return true }
  return false
})
if (!clicked) throw new Error('apply button not found')

const blobsBefore = await page.evaluate(() => Array.from(document.querySelectorAll('img[src^="blob:"]')).map((i) => i.src))
let resultUrl = null
for (let i = 0; i < 40; i++) {
  await sleep(500)
  const now = await page.evaluate(() => Array.from(document.querySelectorAll('img[src^="blob:"]')).map((i) => i.src))
  const fresh = now.filter((s) => !blobsBefore.includes(s))
  if (fresh.length) { resultUrl = fresh[fresh.length - 1]; break }
}
await sleep(400)
const after = await overlayHasStrokes()

const pinkLeft = resultUrl ? await page.evaluate((src) => new Promise((resolve) => {
  const img = new Image()
  img.onload = () => {
    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height
    const ctx = c.getContext('2d'); ctx.drawImage(img, 0, 0)
    const p = ctx.getImageData(100, 75, 1, 1).data
    resolve(p[0] > 200 && p[2] < 200)
  }
  img.src = src
}), resultUrl) : null

console.log('strokes present before apply :', before === 1 ? 'YES' : before === 0 ? 'NO' : 'overlay-not-found')
console.log('overlay cleared after apply  :', after === 0 ? 'YES ✓' : after === 1 ? 'NO ✗' : 'overlay-not-found')
console.log('result watermark pink residue:', resultUrl ? (pinkLeft ? 'YES ✗' : 'none ✓') : 'no-result-image')
await browser.close()
